use core::fmt;
use core::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::Error;

/// Identifies one fling for its whole life: preview, file stream, acknowledgements and history.
///
/// Generated by the sender from 16 random bytes; this crate does no randomness itself.
#[cfg_attr(feature = "arbitrary", derive(arbitrary::Arbitrary))]
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct FlingId(pub [u8; 16]);

/// An iroh endpoint public key (Ed25519, 32 bytes). Peers are identified by this, never by IP address.
#[cfg_attr(feature = "arbitrary", derive(arbitrary::Arbitrary))]
#[derive(Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct EndpointId(pub [u8; 32]);

fn write_hex(f: &mut fmt::Formatter<'_>, bytes: &[u8]) -> fmt::Result {
    bytes.iter().try_for_each(|b| write!(f, "{b:02x}"))
}

fn parse_hex<const N: usize>(s: &str) -> Result<[u8; N], Error> {
    if s.len() != N * 2 || !s.is_ascii() {
        return Err(Error::Malformed(format!(
            "expected {} hex characters",
            N * 2
        )));
    }
    let mut out = [0u8; N];
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16)
            .map_err(|_| Error::Malformed("non-hex character".into()))?;
    }
    Ok(out)
}

macro_rules! hex_id {
    ($ty:ident, $n:literal) => {
        impl fmt::Display for $ty {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write_hex(f, &self.0)
            }
        }

        impl fmt::Debug for $ty {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, concat!(stringify!($ty), "("))?;
                write_hex(f, &self.0)?;
                f.write_str(")")
            }
        }

        impl FromStr for $ty {
            type Err = Error;

            fn from_str(s: &str) -> Result<Self, Error> {
                parse_hex::<$n>(s).map(Self)
            }
        }
    };
}

hex_id!(FlingId, 16);
hex_id!(EndpointId, 32);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fling_id_round_trips_through_hex() {
        let id = FlingId([0xab; 16]);
        let text = id.to_string();
        assert_eq!(text.len(), 32);
        assert_eq!(text.parse::<FlingId>().unwrap(), id);
    }

    #[test]
    fn rejects_wrong_length_and_non_hex() {
        assert!("abc".parse::<EndpointId>().is_err());
        assert!("zz".repeat(32).parse::<EndpointId>().is_err());
        assert!("é".repeat(32).parse::<EndpointId>().is_err());
    }
}
